alter sequence counter as bigint increment by 1 minvalue 1 maxvalue 9223372036854775807 start with 1000 cache 1 no cycle;
do $reylo$ declare s regclass := 'public.counter'; stands numeric; goal numeric := 1000; reach numeric; low numeric; high numeric; c record; begin select seqmin, seqmax into low, high from pg_sequence where seqrelid = s; execute format('select case when is_called then last_value::numeric + (1) else last_value end from %s', s) into stands; for c in select d.refobjid::regclass as rel, a.attname from pg_depend d join pg_attribute a on a.attrelid = d.refobjid and a.attnum = d.refobjsubid where d.classid = 'pg_class'::regclass and d.objid = s and d.refclassid = 'pg_class'::regclass and d.deptype in ('a', 'i') union select ad.adrelid::regclass, a.attname from pg_depend d join pg_attrdef ad on ad.oid = d.objid join pg_attribute a on a.attrelid = ad.adrelid and a.attnum = ad.adnum where d.classid = 'pg_attrdef'::regclass and d.refclassid = 'pg_class'::regclass and d.refobjid = s loop execute format('select max(%I)::numeric + 1 from %s', c.attname, c.rel) into reach; if reach > goal and reach between low and high then goal := reach; end if; end loop; if goal > stands and goal between low and high then perform setval(s, goal::bigint, false); end if; end $reylo$;
